-- #335 fase 2h — captura de catálogo idêntica para Live e harness (só pg_catalog; sem linhas de dados).
-- Mesma metodologia/categorias do phase2f-catalog-differential.json, alargada a todos os schemas
-- não-sistema e excluindo membros das extensões instaladas de verdade (iguais por construção).
WITH sch AS (SELECT oid, nspname FROM pg_namespace WHERE nspname !~ '^pg_' AND nspname<>'information_schema'),
ext AS (SELECT d.classid, d.objid FROM pg_depend d JOIN pg_extension e ON e.oid=d.refobjid
        WHERE d.deptype='e' AND e.extname IN ('plpgsql','vector','uuid-ossp','pgcrypto','unaccent','pg_trgm')),
rel AS (SELECT c.* FROM pg_class c JOIN sch ON sch.oid=c.relnamespace
        WHERE NOT EXISTS(SELECT 1 FROM ext WHERE classid='pg_class'::regclass AND objid=c.oid))
SELECT jsonb_build_object(
 'relations',(SELECT jsonb_agg(jsonb_build_object('schema',relnamespace::regnamespace::text,'name',relname,'kind',relkind,'owner',pg_get_userbyid(relowner),'acl',relacl::text,'rls',relrowsecurity,'force_rls',relforcerowsecurity,'options',reloptions)) FROM rel WHERE relkind IN ('r','p','v','m','S','f')),
 'columns',(SELECT jsonb_agg(jsonb_build_object('table',a.attrelid::regclass::text,'name',a.attname,'position',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid),'collation',a.attcollation::regcollation::text,'acl',a.attacl::text)) FROM pg_attribute a JOIN rel c ON c.oid=a.attrelid LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE c.relkind IN ('r','p','v','m') AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('table',conrelid::regclass::text,'type_owner',contypid::regtype::text,'name',conname,'type',contype,'validated',convalidated,'deferrable',condeferrable,'deferred',condeferred,'definition',pg_get_constraintdef(k.oid))) FROM pg_constraint k JOIN sch ON sch.oid=k.connamespace WHERE contype<>'n' AND (conrelid=0 OR conrelid IN (SELECT oid FROM rel)) AND NOT EXISTS(SELECT 1 FROM ext WHERE classid='pg_type'::regclass AND objid=k.contypid)),
 'indexes',(SELECT jsonb_agg(jsonb_build_object('table',i.indrelid::regclass::text,'name',c.relname,'definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready)) FROM pg_index i JOIN rel c ON c.oid=i.indexrelid),
 'triggers',(SELECT jsonb_agg(jsonb_build_object('table',tgrelid::regclass::text,'name',CASE WHEN tgisinternal THEN 'RI:'||tgfoid::regproc::text||':'||tgtype||':'||coalesce(tgconstraint::regclass::text,'')||':'||(SELECT conname FROM pg_constraint WHERE oid=t.tgconstraint) ELSE tgname END,'internal',tgisinternal,'enabled',tgenabled,'definition',CASE WHEN tgisinternal THEN NULL ELSE pg_get_triggerdef(t.oid) END,'function',tgfoid::regprocedure::text)) FROM pg_trigger t WHERE tgrelid IN (SELECT oid FROM rel)),
 'policies',(SELECT jsonb_agg(to_jsonb(p)) FROM pg_policies p WHERE schemaname IN (SELECT nspname FROM sch)),
 'functions',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'kind',p.prokind,'language',(SELECT lanname FROM pg_language WHERE oid=p.prolang),'definition',CASE WHEN p.prolang IN (12,13) THEN 'C/internal' ELSE pg_get_functiondef(p.oid) END,'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,'secdef',p.prosecdef,'config',p.proconfig,'volatile',p.provolatile,'strict',p.proisstrict,'leakproof',p.proleakproof,'parallel',p.proparallel)) FROM pg_proc p JOIN sch ON sch.oid=p.pronamespace WHERE p.prokind IN ('f','p','a','w') AND NOT EXISTS(SELECT 1 FROM ext WHERE classid='pg_proc'::regclass AND objid=p.oid)),
 'types',(SELECT jsonb_agg(jsonb_build_object('name',format('%I.%I',sch.nspname,t.typname),'type',t.typtype,'owner',pg_get_userbyid(t.typowner),'labels',(SELECT jsonb_agg(enumlabel ORDER BY enumsortorder) FROM pg_enum WHERE enumtypid=t.oid),'base',CASE WHEN t.typtype='d' THEN format_type(t.typbasetype,t.typtypmod) END,'notnull',t.typnotnull,'default',t.typdefault,'acl',t.typacl::text)) FROM pg_type t JOIN sch ON sch.oid=t.typnamespace WHERE t.typtype IN ('e','d','r') OR (t.typtype='c' AND (SELECT relkind FROM pg_class WHERE oid=t.typrelid)='c') AND NOT EXISTS(SELECT 1 FROM ext WHERE classid='pg_type'::regclass AND objid=t.oid)),
 'sequences',(SELECT jsonb_agg(jsonb_build_object('name',seqrelid::regclass::text,'type',format_type(seqtypid,NULL),'start',seqstart,'inc',seqincrement,'min',seqmin,'max',seqmax,'cache',seqcache,'cycle',seqcycle)) FROM pg_sequence WHERE seqrelid IN (SELECT oid FROM rel)),
 'views',(SELECT jsonb_agg(jsonb_build_object('name',oid::regclass::text,'definition',pg_get_viewdef(oid))) FROM rel WHERE relkind IN ('v','m')),
 'default_acl',(SELECT jsonb_agg(jsonb_build_object('role',pg_get_userbyid(defaclrole),'schema',defaclnamespace::regnamespace::text,'type',defaclobjtype,'acl',defaclacl::text)) FROM pg_default_acl),
 'schemas',(SELECT jsonb_agg(jsonb_build_object('name',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl::text)) FROM pg_namespace WHERE oid IN (SELECT oid FROM sch)),
 'extensions',(SELECT jsonb_agg(jsonb_build_object('name',extname,'schema',extnamespace::regnamespace::text,'version',extversion)) FROM pg_extension),
 'roles',(SELECT jsonb_agg(jsonb_build_object('name',rolname,'super',rolsuper,'bypass',rolbypassrls,'create',rolcreaterole,'createdb',rolcreatedb,'login',rolcanlogin,'replication',rolreplication,'inherit',rolinherit)) FROM pg_roles WHERE rolname NOT LIKE 'pg_%'),
 'memberships',(SELECT jsonb_agg(jsonb_build_object('role',pg_get_userbyid(roleid),'member',pg_get_userbyid(member),'grantor',pg_get_userbyid(grantor),'admin',admin_option,'inherit',inherit_option,'set',set_option)) FROM pg_auth_members WHERE NOT (pg_get_userbyid(roleid) LIKE 'pg_%' AND pg_get_userbyid(member) LIKE 'pg_%'))
)::text;
